css:
h3, p {
    text-align: center;
    margin: 5px 0;
}
table {
    width: 100%;
    border-collapse: collapse;
    font-size: 11px;
    direction: rtl;
}
th, td {
    border: 1px solid #000;
    padding: 4px;
    text-align: center;
}
thead th {
    background-color: #dfeef3;
    font-weight: bold;
}
tfoot td {
    background-color: #f3f3f3;
    font-weight: bold;
}
